def transform(grid):
 h=len(grid);w=len(grid[0]);out=[r[:] for r in grid]
 pts={(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0}
 while pts:
  p=pts.pop(); group={p}; stack=[p]
  while stack:
   r,c=stack.pop()
   for dr in range(-2,3):
    for dc in range(-2,3):
     q=(r+dr,c+dc)
     if q in pts:
      pts.remove(q);group.add(q);stack.append(q)
  if len(group)==1: continue
  a=min(r for r,c in group);b=min(c for r,c in group)
  n=max(max(r for r,c in group)-a+1,max(c for r,c in group)-b+1)
  colors={grid[r][c] for r,c in group}
  seen={next(iter(group))};todo=list(seen)
  while todo:
   r,c=todo.pop()
   for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
    q=r+dr,c+dc
    if q in group and q not in seen:seen.add(q);todo.append(q)
  color=next(iter(colors)) if len(colors)==1 and seen==group else 5
  for r in range(a,min(h,a+n)):
   for c in range(b,min(w,b+n)):out[r][c]=color
 return out

